265	    // Compare user given block location against allocatedBlockLocations
266	    // present in OmKeyInfo.
267	    List<OmKeyLocationInfo> uncommittedBlocks;
268	    List<OmKeyLocationInfo> updatedBlockLocations;
269	    if (skipBlockIDCheck) {
270	      updatedBlockLocations = locationInfoList;
271	      uncommittedBlocks = new ArrayList<>();
272	    } else {
273	      Pair<List<OmKeyLocationInfo>, List<OmKeyLocationInfo>> verifiedResult =
